import re

def _get_node(doc, title):
    for n in doc.get("nodes", []):
        if n.get("title") == title:
            return n
    return None

def _parse_table(node):
    if node.get("kind") != "table":
        return [], []
    tbl = node.get("table", {})
    return tbl.get("columns", []), tbl.get("rows", [])

def _row_to_dict(cols, row):
    return {c: row[i] for i, c in enumerate(cols) if i < len(row)}

def entities(doc, scope):
    scope_node = _get_node(doc, scope)
    if not scope_node: return []

    prod_node = None
    for n in doc["nodes"]:
        if n.get("parent_id") == scope_node["node_id"] and "Products" in n.get("title", ""):
            prod_node = n
            break

    if not prod_node: return []
    cols, rows = _parse_table(prod_node)
    prods = []
    for r in rows:
        d = _row_to_dict(cols, r)
        pid = d.get("product", "")
        if pid:
            prods.append({"id": pid, "description": pid})
    return prods

def recorded_end(doc, scope):
    scope_node = _get_node(doc, scope)
    if not scope_node: return 14.0
    for n in doc["nodes"]:
        if n.get("parent_id") == scope_node["node_id"] and "Daily ledger" in n.get("title", ""):
            cols, rows = _parse_table(n)
            max_day = 0
            for r in rows:
                d = _row_to_dict(cols, r)
                try:
                    day = int(d.get("day", 0))
                    if day > max_day: max_day = day
                except: pass
            return float(max_day) if max_day > 0 else 14.0
    return 14.0

